const csvText = $input.first().json.data || $input.first().body || '';

if (!csvText || csvText.includes('<!DOCTYPE html>') || csvText.includes('<html')) {
  throw new Error('Google Sheet belum di-Share ke Public! Buka Google Sheet -> Share -> Ganti ke "Anyone with the link can view"');
}

// Parse CSV text into JSON items
function parseCSV(text) {
  const lines = text.split(/\r?\n/).filter(line => line.trim());
  if (lines.length < 2) return [];

  // Parse Header row
  const parseLine = (line) => {
    const values = [];
    let val = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (char === '"') inQuotes = !inQuotes;
      else if (char === ',' && !inQuotes) {
        values.push(val.trim().replace(/^"|"$/g, ''));
        val = '';
      } else val += char;
    }
    values.push(val.trim().replace(/^"|"$/g, ''));
    return values;
  };

  const headers = parseLine(lines[0]);
  const results = [];

  for (let i = 1; i < lines.length; i++) {
    const currentline = parseLine(lines[i]);
    const rowObj = {};
    headers.forEach((header, index) => {
      rowObj[header] = currentline[index] || '';
    });
    results.push({ json: rowObj });
  }
  return results;
}

return parseCSV(csvText);

const getVal = (possibleKeys) => {
  for (const k of possibleKeys) {
    const foundKey = Object.keys($json).find(key => key.trim().toLowerCase().includes(k.toLowerCase()));
    if (foundKey && $json[foundKey]) return String($json[foundKey]).trim();
  }
  return '';
};

